export function findById(id){return APIS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return APIS.slice();return APIS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export const COUNT=APIS.length;

